const url = msg.payload.url || msg.payload;
const device = msg.payload.device || 'mobile';

if (!url || !url.startsWith('http')) {
  node.error('URL invalide. Fournir une URL complète (https://...)', msg);
  return null;
}

if (!['mobile', 'desktop'].includes(device)) {
  node.warn('device doit être "mobile" ou "desktop". Utilisation de "mobile" par défaut.');
}

msg.auditUrl = url;
msg.auditDevice = device;
msg.auditTimestamp = new Date().toISOString();
msg.auditSlug = url
  .replace(/https?:\/\//, '')
  .replace(/[^a-z0-9]+/gi, '-')
  .replace(/^-|-$/g, '')
  .toLowerCase();

node.status({ fill: 'blue', shape: 'dot', text: `Audit en cours : ${url}` });
return msg;

// Lighthouse est lancé via le conteneur satellite 'kpsy_lighthouse'
// qui tourne sur le même réseau Docker automation_net
// Node-RED appelle son endpoint HTTP interne

const reportPath = `/reports/lh-${msg.auditSlug}-${msg.auditTimestamp.slice(0,10)}.json`;

msg.lighthouseCmd = {
  url: msg.auditUrl,
  device: msg.auditDevice,
  reportPath: reportPath
};

// Appel HTTP vers le conteneur Lighthouse satellite
// (le script runner.sh y expose un endpoint minimaliste)
msg.payload = {
  url: msg.auditUrl,
  formFactor: msg.auditDevice === 'desktop' ? 'desktop' : 'mobile',
  outputPath: reportPath
};

return msg;

const { url, device } = msg.payload;
const timestamp = new Date().toISOString().slice(0, 10);
const slug = url.replace(/https?:\/\//, '').replace(/[^a-z0-9]+/gi, '-').toLowerCase();
const outFile = `/reports/lh-${slug}-${timestamp}.json`;

msg.outputFile = outFile;
msg.payload = `"${url}" --output=json --output-path="${outFile}" --form-factor="${device}" --chrome-flags="--headless --no-sandbox --disable-dev-shm-usage" --quiet`;

return msg;

// Lire le fichier JSON généré par Lighthouse
const fs = require('fs');

let reportPath;
try {
  // Le path est passé dans msg.outputFile par le nœud précédent
  reportPath = msg.outputFile || '/reports/lighthouse-latest.json';
  const raw = fs.readFileSync(reportPath, 'utf8');
  const report = JSON.parse(raw);

  const cats = report.categories;
  msg.scores = {
    performance:   Math.round((cats.performance?.score || 0) * 100),
    accessibility: Math.round((cats.accessibility?.score || 0) * 100),
    bestPractices: Math.round((cats['best-practices']?.score || 0) * 100),
    seo:           Math.round((cats.seo?.score || 0) * 100)
  };

  // Extraire les audits échoués (score < 0.9)
  const failedAudits = Object.values(report.audits)
    .filter(a => a.score !== null && a.score < 0.9)
    .sort((a, b) => (a.score || 0) - (b.score || 0))
    .slice(0, 20)
    .map(a => ({
      id: a.id,
      title: a.title,
      description: a.description?.slice(0, 200),
      score: Math.round((a.score || 0) * 100),
      displayValue: a.displayValue || ''
    }));

  msg.failedAudits = failedAudits;
  msg.auditUrl = report.finalUrl || msg.auditUrl;

  node.status({ fill: 'green', shape: 'dot', text: `Perf: ${msg.scores.performance} | SEO: ${msg.scores.seo}` });
  node.log(`Lighthouse OK — Perf: ${msg.scores.performance}, SEO: ${msg.scores.seo}, A11y: ${msg.scores.accessibility}`);
  return msg;

} catch(e) {
  node.error(`Impossible de parser le rapport Lighthouse : ${e.message}`, msg);
  node.status({ fill: 'red', shape: 'ring', text: 'Erreur parsing' });
  return null;
}

if (msg.payload && msg.payload.trim()) {
  node.warn(`Lighthouse stderr: ${msg.payload}`);
}
return null;

node.error('Lighthouse timeout après 120s — La page est peut-être inaccessible ou Chrome headless a planté.', msg);
node.status({ fill: 'red', shape: 'ring', text: 'Timeout' });
return null;

const { scores, failedAudits, auditUrl } = msg;

const failedList = failedAudits.map(a => 
  `- [Score: ${a.score}/100] **${a.title}** (${a.displayValue})`
).join('
');

const systemPrompt = `Tu es un expert en performance web et SEO technique. Tu analyses des rapports Lighthouse et produis des synthèses priorisées, concrètes et actionnables en français.`;

const userPrompt = `Voici le rapport Lighthouse pour la page : ${auditUrl}

## Scores globaux
- Performance : ${scores.performance}/100
- Accessibilité : ${scores.accessibility}/100
- Bonnes pratiques : ${scores.bestPractices}/100
- SEO : ${scores.seo}/100

## Audits échoués (les plus impactants)
${failedList}

Génère une synthèse structurée en Markdown avec :

### 🔴 Problèmes Critiques (à corriger en priorité absolue)
(Impact fort sur performance/SEO/conversion — action requise sous 48h)

### 🟡 Améliorations Majeures
(Impact modéré — à planifier dans les 2 semaines)

### 🟢 Optimisations Mineures
(Gains marginaux — quick wins si possible)

### 📈 Estimation de gain attendu
(Impact sur le score Performance et SEO si les corrections critiques sont appliquées)

Sois très concret : indique les fichiers/ressources concernés quand tu les connais, les outils à utiliser, les configs à modifier.`;

msg.claudeRequest = {
  model: 'claude-3-haiku-20240307',
  max_tokens: 2048,
  system: systemPrompt,
  messages: [{ role: 'user', content: userPrompt }]
};

return msg;

const apiKey = flow.get('claude_api_key') || env.get('CLAUDE_API_KEY');
if (!apiKey) {
  node.error('Clé API Claude manquante', msg);
  return null;
}
msg.headers = {
  'Content-Type': 'application/json',
  'x-api-key': apiKey,
  'anthropic-version': '2023-06-01'
};
msg.payload = msg.claudeRequest;
return msg;

if (msg.statusCode !== 200) {
  node.error(`Erreur Claude ${msg.statusCode}`, msg);
  return null;
}

const synthesis = msg.payload?.content?.[0]?.text || 'Erreur : réponse Claude vide';
const { scores, auditUrl, auditTimestamp, auditSlug } = msg;

const report = `# Rapport d'audit Lighthouse\n` +
  `**URL :** ${auditUrl}  \n` +
  `**Date :** ${auditTimestamp}  \n` +
  `**Device :** ${msg.auditDevice || 'mobile'}\n\n` +
  `## 📊 Scores Lighthouse\n` +
  `| Catégorie | Score |\n|---|---|\n` +
  `| Performance | ${scores.performance}/100 |\n` +
  `| SEO | ${scores.seo}/100 |\n` +
  `| Accessibilité | ${scores.accessibility}/100 |\n` +
  `| Bonnes pratiques | ${scores.bestPractices}/100 |\n\n` +
  `---\n\n` + synthesis;

const filename = `/data/audits/${auditTimestamp.slice(0,10)}_${auditSlug}.md`;
msg.filename = filename;
msg.payload = report;

node.log(`Rapport audit sauvegardé : ${filename}`);
return msg;
